import { useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { postJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { usePeople } from '../people/people';
import { poolsKey, usePools, type Pool, type PoolMember } from './pools';

/** One pool: its total share and whether it is balanced, each member's line with their share, and the picker that adds
 *  a person with a share. A person already in the pool, or a share not more than 0.00 and at most 100.00 with two
 *  decimals, is refused with the pool's error. */
function PoolRow({ sheetId, user, pool }: { sheetId: string; user: string; pool: Pool }) {
  const people = usePeople(sheetId);
  const queryClient = useQueryClient();
  const [chosen, setChosen] = useState('');
  const [share, setShare] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (m: { personId: number; share: string }) =>
      postJson<PoolMember>(`/api/sheets/${encodeURIComponent(sheetId)}/pools/members`, { pool: pool.name, ...m, by: user }),
    onSuccess: async () => {
      setChosen('');
      setShare('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <li data-testid={`pool-row-${pool.name}`}>
      <strong>{pool.name}</strong> — total <span data-testid="pool-total-share">{pool.totalShare.toFixed(2)}</span>, balanced{' '}
      <span data-testid="pool-balanced">{pool.balanced ? 'yes' : 'no'}</span>
      <ul>
        {pool.members.map((m) => (
          <li key={m.personId} data-testid={`pool-member-${pool.name}-${m.personId}`}>
            {m.name}: <span data-testid="pool-share">{m.share.toFixed(2)}</span>
            {m.retired && ' (retired)'}
          </li>
        ))}
      </ul>
      <select
        data-testid="pool-member-select"
        value={chosen}
        onChange={(e) => {
          setChosen(e.target.value);
          add.reset();
        }}
      >
        <option value="">Person…</option>
        {(people.data ?? []).map((p) => (
          <option key={p.id} value={String(p.id)}>
            {p.name}
          </option>
        ))}
      </select>{' '}
      <input
        data-testid="pool-member-share"
        placeholder="Share %"
        value={share}
        onChange={(e) => {
          setShare(e.target.value);
          add.reset();
        }}
      />{' '}
      <button
        type="button"
        data-testid="pool-member-add"
        disabled={add.isPending}
        onClick={() => {
          if (!submit.begin()) return;
          add.reset();
          add.mutate({ personId: Number(chosen), share }); // nothing chosen: no person 0, so the server refuses it
        }}
      >
        Add member
      </button>
      {add.isError && <span data-testid="pool-error"> Could not add this member.</span>}
    </li>
  );
}

/** The sheet's pools: the form that adds one (its name trimmed, not blank, not already taken), and each pool's row. */
function Pools({ sheetId, user }: { sheetId: string; user: string }) {
  const pools = usePools(sheetId);
  const queryClient = useQueryClient();
  const [name, setName] = useState('');

  const submit = useSubmitOnce();
  const add = useMutation({
    mutationFn: (n: string) => postJson<Pool>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`, { name: n, by: user }),
    onSuccess: async () => {
      setName('');
      await queryClient.invalidateQueries({ queryKey: poolsKey(sheetId) });
    },
    onSettled: submit.end,
  });

  return (
    <section data-testid="pools">
      <h3>Pools</h3>
      <form
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          add.reset();
          add.mutate(name);
        }}
      >
        <input
          data-testid="pool-form-name"
          placeholder="Pool name"
          value={name}
          onChange={(e) => {
            setName(e.target.value);
            add.reset();
          }}
        />{' '}
        <button type="submit" data-testid="pool-form-submit" disabled={add.isPending}>
          Add pool
        </button>
        {add.isError && <span data-testid="pool-form-error"> A pool's name must not be blank nor already taken.</span>}
      </form>
      {pools.isError && <p data-testid="pools-load-error">Could not load pools.</p>}
      <ul>
        {(pools.data ?? []).map((p) => (
          <PoolRow key={p.name} sheetId={sheetId} user={user} pool={p} />
        ))}
      </ul>
    </section>
  );
}

export const contribution = SheetPage.fill({ order: 9.7, Component: Pools });
import { useQuery } from '@tanstack/react-query';
import { getJson } from '../../api/http';
import { peopleKey } from '../people/people';

/** A member of a pool: the person, their `share` percent (two decimals; a JSON number, shown with two), and whether they are `retired` (a retirement
 *  date set, whatever the date): then their share counts as 0.00 toward the pool's total. */
export type PoolMember = { personId: number; name: string; share: number; retired: boolean };

/** A pool of the sheet: its `name` (trimmed, unique on the sheet), its members in the order added, the `totalShare`
 *  of their shares, and whether it is `balanced` (a total of exactly 100.00). A person can be in several pools. */
export type Pool = { name: string; members: PoolMember[]; totalShare: number; balanced: boolean };

/** Under the people's key, so every change to a person (a retirement above all) reloads the totals. */
export const poolsKey = (sheetId: string) => [...peopleKey(sheetId), 'pools'];

/** The sheet's pools, in the order added. */
export function usePools(sheetId: string) {
  return useQuery({
    queryKey: poolsKey(sheetId),
    queryFn: () => getJson<Pool[]>(`/api/sheets/${encodeURIComponent(sheetId)}/pools`),
  });
}
import { useRef, useState } from 'react';
import { useMutation, useQueryClient } from '@tanstack/react-query';
import { putJson } from '../../api/http';
import { useSubmitOnce } from '../../query/useSubmitOnce';
import { SheetPage } from '../../slots/defs/sheetPage';
import { useSheetToday } from '../session/session';
import { DEFAULT_FLOOR, DEFAULT_LATE_PCT, DEFAULT_TERMS, inForce, settingsKey, useSettings, type Setting } from './settings';

const GRADES = ['A', 'B', 'C'] as const;
type GradeTerms = `terms-${(typeof GRADES)[number]}`;
type GradeGrace = `grace-${(typeof GRADES)[number]}`;
type GradeProof = `proof-threshold-${(typeof GRADES)[number]}`;
const PERM_ACTIONS = ['open', 'settle', 'void', 'reassign', 'close', 'reopen'] as const;
type PermKey = `perm-${(typeof PERM_ACTIONS)[number]}`;
const PERM_KEYS: PermKey[] = PERM_ACTIONS.map((a) => `perm-${a}` as PermKey);
type Key = PermKey | 'clerk-limit' | 'cap' | 'proof-threshold' | 'note-threshold' | 'floor' | 'terms' | GradeTerms | GradeGrace | GradeProof | 'late-pct' | 'policy-date' | 'period-numbering-from' | 'entry-date' | 'grace-days';
const KEYS: Key[] = ['clerk-limit', 'cap', 'proof-threshold', 'note-threshold', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'grace-A', 'grace-B', 'grace-C', 'proof-threshold-A', 'proof-threshold-B', 'proof-threshold-C', 'late-pct', 'policy-date', 'period-numbering-from', 'entry-date', 'grace-days', ...PERM_KEYS];
const BLANK: Record<Key, string> = {
  'clerk-limit': '', cap: '', 'proof-threshold': '', 'note-threshold': '', floor: '', terms: '', 'terms-A': '', 'terms-B': '', 'terms-C': '', 'grace-A': '', 'grace-B': '', 'grace-C': '', 'proof-threshold-A': '', 'proof-threshold-B': '', 'proof-threshold-C': '', 'late-pct': '', 'policy-date': '', 'period-numbering-from': '', 'entry-date': '', 'grace-days': '',
  ...(Object.fromEntries(PERM_KEYS.map((k) => [k, ''])) as Record<PermKey, string>),
};
/** The keys whose values are dated: each saved from a from-date (blank: the sheet's today). */
const DATED: Key[] = ['clerk-limit', 'cap', 'proof-threshold', 'note-threshold', 'floor', 'terms', 'terms-A', 'terms-B', 'terms-C', 'grace-A', 'grace-B', 'grace-C', 'proof-threshold-A', 'proof-threshold-B', 'proof-threshold-C', 'late-pct'];
const dated = (key: Key) => DATED.includes(key);

/** The sheet's settings: the clerk limit (the most a clerk may settle a claim's due for; blank for no limit) and the
 *  cap (the most a person's due-total may be; blank for none) and the proof threshold (a claim whose due is above
 *  the one in force on its date cannot be settled nor approved while it has no proofs; blank for none) and each grade's own proof threshold (a claim whose person has that grade on its date takes the grade's in force on that date instead of the sheet's; blank for none) and the note threshold (a claim whose due is above the one in force on its date cannot be
 *  opened while its note is empty; blank for none) and the floor (the least a claim's live due may be; 1.00 until set) and the terms (the days from a claim's date to its
 *  due-by, fixed when the claim is added; 14 until set) and each grade's own terms (a grade without its own has the
 *  sheet's) and each grade's grace (whole days added to the due-by of a claim whose person has that grade on its date, the one in force on that date, before
 *  it is overdue and its late charge counts; blank for none) and the late percent (what an overdue claim gains of its figure for every full 30 days
 *  overdue; 0.00 until set) and the policy date (yyyy-MM-dd; blank: the sheet's today — a claim dated before it rounds
 *  half up, one on or after it half to even) and the period numbering from-date (yyyy-MM-dd; blank: off — while the sheet's
 *  today is on or after it, a claim opened is numbered within its period) and the entry date (yyyy-MM-dd; blank: off — while set, a new claim given no
 *  date, by the claim form, the quick-add bar, a paste or a correction, is dated it instead of the sheet's today) and the grace days (a whole number; blank: off — when the
 *  sheet's today changes, every open period whose to-date plus them is before the new today is closed) and the permission matrix (for each of open, settle,
 *  void, reassign, close and reopen, the roles that may take it, comma separated; blank: the standing rule — open, settle,
 *  void and close by clerk and steward, reassign and reopen by steward; undated). Every setting but the policy date, the
 *  period numbering from-date, the entry date, the grace days and the permissions is dated: saved with its from-date (blank: the sheet's today) it keeps the values from
 *  other dates, and what shows in force is the value on the sheet's today (a claim takes its floor, late percent and
 *  terms, and proof and note thresholds, from its own date). Saving stores the fields entered since the last save
 *  (a field focused counts, so a blank typed over a blank still saves), the clerk limit when none was. */
function Settings({ sheetId, user }: { sheetId: string; user: string }) {
  const settings = useSettings(sheetId);
  const queryClient = useQueryClient();
  const today = useSheetToday(sheetId);
  const [values, setValues] = useState<Record<Key, string>>(BLANK);
  const [froms, setFroms] = useState<Record<Key, string>>(BLANK);
  const touched = useRef(new Set<Key>());

  const submit = useSubmitOnce();
  const save = useMutation({
    mutationFn: async (entries: [Key, string, string][]) => {
      for (const [key, value, from] of entries) {
        await putJson<Setting>(`/api/sheets/${encodeURIComponent(sheetId)}/settings/${key}`, { value, from, by: user });
      }
    },
    onSuccess: () => {
      setValues(BLANK);
      setFroms(BLANK);
      touched.current.clear();
    },
    onSettled: () => {
      submit.end();
      void queryClient.invalidateQueries({ queryKey: settingsKey(sheetId) });
    },
  });
  const current = (key: Key) => (dated(key) ? inForce(settings.data, key, today) : settings.data?.find((s) => s.key === key))?.value ?? '';

  const field = (key: Key, label: string, inputMode: 'decimal' | 'numeric' | 'text' = 'decimal') => (
    <label>
      {label}{' '}
      <input
        data-testid={`setting-${key}`}
        inputMode={inputMode}
        value={values[key]}
        onFocus={() => touched.current.add(key)}
        onChange={(e) => {
          touched.current.add(key);
          const value = e.target.value;
          setValues((was) => ({ ...was, [key]: value }));
          save.reset();
        }}
      />
      {dated(key) && (
        <>
          {' '}from{' '}
          <input
            data-testid={`setting-${key}-from`}
            inputMode="numeric"
            placeholder="yyyy-MM-dd"
            value={froms[key]}
            onFocus={() => touched.current.add(key)}
            onChange={(e) => {
              touched.current.add(key);
              const from = e.target.value;
              setFroms((was) => ({ ...was, [key]: from }));
              save.reset();
            }}
          />
        </>
      )}
    </label>
  );

  return (
    <section data-testid="settings">
      <h3>Settings</h3>
      <form
        data-testid="settings-form"
        onSubmit={(e) => {
          e.preventDefault();
          if (!submit.begin()) return;
          save.reset();
          const keys = KEYS.filter((k) => touched.current.has(k));
          save.mutate((keys.length > 0 ? keys : (['clerk-limit'] as Key[])).map((k) => [k, values[k], froms[k]]));
